package io.zenwave360.language.docs.internal

import io.zenwave360.language.docs.DocsSource

/** First line of every generated file. Only generated files are overwritten or deleted: DocsFolder only deletes files that start with it. */
internal const val GENERATED_MARKER = "<!-- Generated by dsl-docs. Do not edit: changes are overwritten. -->"

internal object Markdown {

    /** The marker and the sources a page was generated from, with the SHA-256 of each. */
    fun header(sources: List<DocsSource>): String = buildString {
        append(GENERATED_MARKER).append('\n')
        for (source in sources) {
            append("<!-- Source: ").append(comment(source.path)).append(" sha256:").append(Sha256.hex(source.content)).append(" -->\n")
        }
        append('\n')
    }

    fun mermaid(diagram: String): String = "```mermaid\n${diagram.trimEnd()}\n```\n"

    /** A table, or nothing when there are no rows. Cells are kept on one line and `|` is escaped. */
    fun table(headers: List<String>, rows: List<List<String?>>): String {
        if (rows.isEmpty()) return ""
        return buildString {
            append("| ").append(headers.joinToString(" | ") { cell(it) }).append(" |\n")
            append("|").append(headers.joinToString("|") { " --- " }).append("|\n")
            for (row in rows) append("| ").append(row.joinToString(" | ") { cell(it) }).append(" |\n")
        }
    }

    fun code(text: String): String = if (text.isEmpty()) "" else "`${text.replace("`", "'")}`"

    /** Text on one line: Javadoc and descriptions often span lines, and tables and headings cannot. */
    fun inline(text: String?): String = text.orEmpty().trim().replace(Regex("\\s+"), " ")

    /**
     * [inline] for text that must not bring markup of its own into the page, as in a preview: backslashes, `<`, `>`, `[` and `]`
     * are escaped, so raw HTML (`<script>`, `<img src=...>`) and Markdown links and images show as plain text, and `://` is
     * escaped so a URL is not turned into a link. The text is still readable, and the page has nothing that loads or runs.
     */
    fun safeInline(text: String?): String = inline(text)
        .replace("\\", "\\\\").replace("<", "&lt;").replace(">", "&gt;")
        .replace("[", "\\[").replace("]", "\\]").replace("://", "\\://")

    /**
     * Text shown as written, in a table cell or a line: [safeInline] and also the characters that format (`*`, `_`, backtick, `~`)
     * escaped, so a value such as `*.java` or `my_file` reads as it is and cannot become emphasis or code.
     */
    fun safeLiteral(text: String?): String = safeInline(text).replace("*", "\\*").replace("_", "\\_").replace("`", "\\`").replace("~", "\\~")

    /**
     * Javadoc as safe CommonMark. Each source line ends in a CommonMark hard break; empty lines remain paragraph breaks.
     * Markdown emphasis, lists and inline code are retained, while raw HTML, images and links are text. Headings, quotes,
     * rules, fences and tables are escaped so the Javadoc cannot alter the page structure or its generated fences.
     */
    fun safeJavadoc(text: String?): String {
        val lines = text.orEmpty().lines().map { it.trim().removePrefix("*").trimStart() }
        return buildString {
            lines.forEachIndexed { index, line ->
                append(safeJavadocLine(line))
                if (line.isNotBlank() && index < lines.lastIndex) append("  ")
                if (index < lines.lastIndex) append('\n')
            }
        }
    }

    /**
     * [safeInline] for the text of a heading. A closing run of `#` is escaped: the client reads it as the end of the heading and
     * would number the heading by the text without it.
     */
    fun safeHeading(text: String?): String = safeInline(text).replace(Regex("#+$")) { "\\" + it.value }

    /** Javadoc text on one line. The ZDL parser keeps the leading `*` of continuation lines. */
    fun javadoc(text: String?): String = inline(text.orEmpty().lines().joinToString("\n") { it.trim().removePrefix("*") })

    /** A blockquote listing the problems found in a source, or nothing. */
    fun problems(problems: List<String>): String {
        if (problems.isEmpty()) return ""
        return buildString {
            append("> **Problems** (this section may be incomplete):\n")
            problems.forEach { append("> - ").append(inline(it)).append('\n') }
            append('\n')
        }
    }

    private fun safeJavadocLine(text: String): String {
        val escaped = safeInline(text).replace("|", "\\|")
        return when {
            HEADING_START.containsMatchIn(escaped) -> "\\$escaped"
            QUOTE_OR_SETEXT_START.containsMatchIn(escaped) -> "\\$escaped"
            RULE_START.containsMatchIn(escaped) -> "\\$escaped"
            FENCE_START.containsMatchIn(escaped) -> "\\$escaped"
            else -> escaped
        }
    }

    private val HEADING_START = Regex("^#{1,6}(?:\\s|$)")
    private val QUOTE_OR_SETEXT_START = Regex("^[>=]")
    private val RULE_START = Regex("^(?:[-*_]\\s*){3,}$")
    private val FENCE_START = Regex("^(?:`{3,}|~{3,})")

    // Same slug rule as GitHub and VS Code headings.
    fun anchor(heading: String): String =
        heading.lowercase().replace(Regex("[^a-z0-9 _-]"), "").replace(' ', '-')

    private fun cell(text: String?): String = inline(text).replace("|", "\\|")

    // A path cannot close the HTML comment it is written in.
    private fun comment(text: String): String = text.replace("--", "-")
}

/** A parser problem as `line L:C: message`; parsers report the location as `[start, end, line, column, ...]`. */
internal fun problemText(problem: Map<String, Any?>): String {
    val location = problem["location"] as? IntArray
    val at = location?.takeIf { it.size >= 4 }?.let { "line ${it[2]}:${it[3]}: " }.orEmpty()
    return "$at${problem["message"]}"
}
